  function sim(q, s) { const r = rng(seed * 101 + s); const T = 60, truth = [], meas = []; let p = 0; for (let t = 0; t < T; t++) { const v = s === 1 && t >= 30 ? -2 : 2; if (t) p += v; truth.push(p); meas.push(p + randn(r) * 2); } const kf = new KF1D(meas[0], 100, q, 4); const est = [kf.x[0]], sd = [Math.sqrt(kf.P[0][0])], nis = []; for (let t = 1; t < T; t++) { kf.predict(); if (!(hide && t >= 40 && t < 50)) { kf.update(meas[t]); if (t > 5) nis.push(kf.y * kf.y / kf.S); } est.push(kf.x[0]); sd.push(Math.sqrt(kf.P[0][0])); } return { truth, meas, est, sd, nis, v: kf.x[1] }; }
