    x.strokeStyle = '#adb5bd'; x.lineWidth = 2; x.beginPath(); R.truth.forEach((v, t) => t ? x.lineTo(X(t), Y(v)) : x.moveTo(X(t), Y(v))); x.stroke(); R.meas.forEach((m, t) => { if (hide && t >= 40 && t < 50) return; x.fillStyle = '#e8590c'; x.beginPath(); x.arc(X(t), Y(m), 2.5, 0, 7); x.fill(); }); x.strokeStyle = '#1c7ed6'; x.lineWidth = 2.5; x.beginPath(); R.est.forEach((v, t) => t ? x.lineTo(X(t), Y(v)) : x.moveTo(X(t), Y(v))); x.stroke(); x.lineWidth = 1;
    [['אמת', '#adb5bd'], ['מדידות', '#e8590c'], ['מסנן ± סטיית תקן', '#1c7ed6']].forEach(([n, c], i) => txt(x, n, 740, 22 + i * 14, c, 11, 'right', true));
