function zoneAlerts(G, inPixels) { const run = {}, al = new Set(); let n = 0, wrong = 0; G.forEach((f, t) => f.outs.forEach(o => { const p = inPixels ? [((o.b[0] + o.b[2]) / 2) * GSD, (o.b[3] + 135) * GSD] : o.g; const ins = pip(p, ZONE); run[o.id] = ins ? (run[o.id] || 0) + 1 : 0; if (run[o.id] >= 5 && !al.has(o.id)) { al.add(o.id); n++; const gt = f.gts.find(q => iou(q.b, o.b) > 0.3); if (!gt || !pip(gt.g, ZONE)) wrong++; } if (!ins) al.delete(o.id); })); return { n, wrong }; }
